import { SurveyBeatApi } from "@surveybeat/api";
import { PERSONAL_DATA_EXPORT_FILENAME, PersonalDataSource } from "@surveybeat/domain";
import type * as Context from "effect/Context";
import * as Clock from "effect/Clock";
import * as Effect from "effect/Effect";
import * as HttpEffect from "effect/http/HttpEffect";
import * as HttpServerResponse from "effect/http/HttpServerResponse";
import * as HttpApiBuilder from "effect/http-api/HttpApiBuilder";
import { authenticated, requireSameOrigin } from "./auth/AuthHandlers.ts";
import type { AuthServices } from "./auth/AuthHandlers.ts";

export type MeServices = AuthServices | PersonalDataSource;

const downloadHeaders = HttpEffect.appendPreResponseHandler((_request, response) =>
  Effect.succeed(
    HttpServerResponse.setHeaders(response, {
      "content-disposition": `attachment; filename="${PERSONAL_DATA_EXPORT_FILENAME}"`,
      "cache-control": "no-store",
    }),
  ),
);

export const meHandlers = <R>(services: Effect.Effect<Context.Context<MeServices>, never, R>) => {
  const provide = <A, E, R2>(effect: Effect.Effect<A, E, R2>) =>
    Effect.flatMap(services, (context) => Effect.provideContext(effect, context));

  return HttpApiBuilder.group(SurveyBeatApi, "me", (handlers) =>
    handlers.handle("exportData", () =>
      provide(
        Effect.gen(function* () {
          yield* requireSameOrigin;
          const checked = yield* authenticated;
          const source = yield* PersonalDataSource;
          const now = yield* Clock.currentTimeMillis;
          yield* downloadHeaders;

          return yield* source.gather(checked.session.identity.userId, now);
        }),
      ),
    ),
  );
};
import type * as Cloudflare from "@alchemy.run/cloudflare";
import {
  assemblePersonalDataExport,
  isoTimestamp,
  OrganizationId,
  PersonalDataSource,
} from "@surveybeat/domain";
import type { AccountData, AuthUserId, OrganizationPersonalData } from "@surveybeat/domain";
import type { RuntimeContext } from "alchemy/RuntimeContext";
import * as DateTime from "effect/DateTime";
import * as Effect from "effect/Effect";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";

const Stamp = Schema.NullOr(Schema.Union([Schema.String, Schema.Finite]));

const UserRow = Schema.Struct({
  id: Schema.String,
  name: Schema.String,
  email: Schema.String,
  emailVerified: Schema.Union([Schema.Finite, Schema.String]),
  createdAt: Stamp,
  updatedAt: Stamp,
});

const SessionRow = Schema.Struct({
  id: Schema.String,
  expiresAt: Stamp,
  createdAt: Stamp,
  updatedAt: Stamp,
  ipAddress: Schema.NullOr(Schema.String),
  userAgent: Schema.NullOr(Schema.String),
});

const LinkRow = Schema.Struct({
  id: Schema.String,
  providerId: Schema.String,
  accountId: Schema.String,
  createdAt: Stamp,
  updatedAt: Stamp,
});

const PasskeyRow = Schema.Struct({
  id: Schema.String,
  name: Schema.NullOr(Schema.String),
  deviceType: Schema.String,
  createdAt: Stamp,
});

const IndexRow = Schema.Struct({
  organization_id: OrganizationId,
  name: Schema.String,
  person_id: Schema.String,
  email: Schema.String,
});

const ClaimRow = Schema.Struct({
  organization_id: OrganizationId,
  name: Schema.String,
  admin_person_id: Schema.String,
  completed_at: Stamp,
});

const isActive = (expiresAt: string | number | null, now: number): boolean => {
  const iso = isoTimestamp(expiresAt);

  return (
    iso !== null && Option.exists(DateTime.make(iso), (expires) => DateTime.toEpochMillis(expires) > now)
  );
};

export const readAccountData = (db: Cloudflare.D1.QueryDatabaseClient) => {
  const all = <S extends Schema.Top & { readonly DecodingServices: never }>(
    schema: S,
    sql: string,
    userId: string,
  ) =>
    db
      .prepare(sql)
      .bind(userId)
      .all()
      .pipe(Effect.flatMap((result) => Schema.decodeEffect(Schema.Array(schema))(result.results)));

  return (userId: AuthUserId, now: number): Effect.Effect<AccountData, never, RuntimeContext> =>
    Effect.gen(function* () {
      const users = yield* all(
        UserRow,
        "SELECT id, name, email, emailVerified, createdAt, updatedAt FROM auth_user WHERE id = ?",
        userId,
      );

      const sessions = yield* all(
        SessionRow,
        `SELECT id, expiresAt, createdAt, updatedAt, ipAddress, userAgent
           FROM auth_session WHERE userId = ? ORDER BY createdAt, id`,
        userId,
      );

      const links = yield* all(
        LinkRow,
        `SELECT id, providerId, accountId, createdAt, updatedAt
           FROM auth_account WHERE userId = ? ORDER BY createdAt, id`,
        userId,
      );

      const passkeys = yield* all(
        PasskeyRow,
        "SELECT id, name, deviceType, createdAt FROM auth_passkey WHERE userId = ? ORDER BY createdAt, id",
        userId,
      );

      const index = yield* all(
        IndexRow,
        `SELECT p.organization_id, o.name, p.person_id, p.email
           FROM person_index p JOIN organizati

... [7291 characters truncated] ...

     done_at: number | null;
      }>`
        SELECT id, team_id, round_id, title, due_date, dimension, status, created_at, updated_at, done_at
          FROM action WHERE owner_id = ${person.id} ORDER BY created_at, id`;

      const emailSends = yield* sql<{
        id: string;
        kind: string | null;
        status: string;
        sent_at: number | null;
        failed_at: number | null;
      }>`
        SELECT id, json_extract(content, '$._tag') AS kind, status,
               json_extract(state, '$.sentAt') AS sent_at, json_extract(state, '$.failedAt') AS failed_at
          FROM email_send WHERE recipient = ${person.email} ORDER BY id`;

      const testSends = yield* sql<{
        send_id: string;
        pulse_id: string;
        pulse_name: string | null;
        sent_at: number;
      }>`
        SELECT test_send.send_id, test_send.pulse_id, pulse.name AS pulse_name, test_send.sent_at
          FROM test_send LEFT JOIN pulse ON pulse.id = test_send.pulse_id
         WHERE test_send.person_id = ${person.id} ORDER BY test_send.sent_at, test_send.send_id`;

      const organization = organizations[0];

      return {
        organization: {
          id: OrganizationId.make(organization?.id ?? ""),
          name: organization?.name ?? "",
        },
        person: {
          id: person.id,
          email: person.email,
          timeZone: person.time_zone,
          locale: person.locale,
          detectedLocale: person.detected_locale,
          organizationAdmin: person.organization_admin === 1,
          removedAt: isoTimestamp(person.removed_at),
        },
        memberships: memberships.map((row) => ({
          id: row.id,
          teamId: row.team_id,
          teamName: row.team_name,
          role: row.role,
          startedAt: isoTimestamp(row.started_at),
          endedAt: isoTimestamp(row.ended_at),
        })),
        participation: participation.map((row) => ({
          roundId: row.round_id,
          plannedOpenDate: row.planned_open_date,
          pulseName: row.pulse_name,
          participated: true as const,
        })),
        roundMembers: roundMembers.map((row) => ({
          roundId: row.round_id,
          plannedOpenDate: row.planned_open_date,
          pulseName: row.pulse_name,
          sendAt: isoTimestamp(row.send_at),
          timeZone: row.time_zone,
        })),
        invitations: invitations.map((row) => ({
          roundId: row.round_id,
          plannedOpenDate: row.planned_open_date,
          pulseName: row.pulse_name,
          status: row.status,
          resendCount: row.resend_count,
          createdAt: isoTimestamp(row.created_at),
          updatedAt: isoTimestamp(row.updated_at),
        })),
        reminderOptOuts: reminderOptOuts.map((row) => ({
          pulseId: row.pulse_id,
          pulseName: row.pulse_name,
          optedOutAt: isoTimestamp(row.opted_out_at),
        })),
        actions: actions.map((row) => ({
          id: row.id,
          teamId: row.team_id,
          roundId: row.round_id,
          title: row.title,
          dueDate: row.due_date,
          dimension: row.dimension,
          status: row.status,
          createdAt: isoTimestamp(row.created_at),
          updatedAt: isoTimestamp(row.updated_at),
          doneAt: isoTimestamp(row.done_at),
        })),
        emailSends: emailSends.map((row) => ({
          id: row.id,
          kind: row.kind ?? "unknown",
          status: row.status,
          sentAt: isoTimestamp(row.sent_at),
          failedAt: isoTimestamp(row.failed_at),
        })),
        testSends: testSends.map((row) => ({
          id: row.send_id,
          pulseId: row.pulse_id,
          pulseName: row.pulse_name,
          sentAt: isoTimestamp(row.sent_at),
        })),
      } satisfies OrganizationPersonalData;
    }).pipe(Effect.orDie),
});
-- The Organization's People (ADR 0002, 0006). A Person exists before signing in (email only) and
-- is linked to an auth user at first sign-in by an exact match on a verified email. The per-request
-- session check asks this table whether the signed-in user's Person is still active.
-- Org-level roles (admin, member) are the Organization's own (SPEC §5.6, ADR 0003), so none is stored here.
CREATE TABLE person (
  id TEXT NOT NULL PRIMARY KEY,
  email TEXT NOT NULL CHECK (email = lower(trim(email))),
  auth_user_id TEXT UNIQUE,
  removed_at INTEGER
) WITHOUT ROWID;
-- Failed attempts of a due job. A job that throws is backed off by nextJobAttemptAt and never cancelled.
ALTER TABLE schedule_job ADD COLUMN failures INTEGER NOT NULL DEFAULT 0;
-- A removed Person stays in the index so an access export can still open that Organization.
-- Sign-in reads only rows with removed_at IS NULL. Adding the same Person again clears it.
ALTER TABLE person_index ADD COLUMN removed_at INTEGER;
