233	export const emailLocaleOf = (state: DirectoryState, personId: PersonId): Locale => {
234	  const person = state.people.find((each) => each.id === personId);
235	
236	  if (person === undefined) {
237	    return state.defaultLocale;
238	  }
239	
240	  return resolveLocale({
241	    person: person.locale,
242	    browser: person.detectedLocale,
243	    organization: state.defaultLocale,
244	  });
245	};
246	
247	const nameTaken = (state: DirectoryState, name: string, except?: TeamId) =>
248	  state.teams.some(
249	    (team) => team.id !== except && team.name.toLocaleLowerCase("en") === name.toLocaleLowerCase("en"),
250	  );
251	
252	const putInTeam = (
253	  state: DirectoryState,
254	  adder: PersonRecord,
255	  team: TeamRecord,
256	  role: AssignableRole,
257	  member: NewMember,
258	  now: number,
259	): Decision => {
260	  const email = EmailAddress.make(normaliseEmail(member.email));
261	  const existing = state.people.find((person) => person.email === email);
262	
263	  if (existing !== undefined && existing.removedAt !== null && !adder.organizationAdmin) {
264	    return reject({ _tag: "PersonWasRemoved" });
265	  }
266	
267	  const person: PersonRecord = existing ?? {
268	    id: member.personId,
269	    email,
270	    authUserId: null,
271	    organizationAdmin: false,
272	    removedAt: null,
273	    locale: null,
274	    detectedLocale: null,
275	  };
276	
277	  const changes: DirectoryChange[] = [];
278	
279	  if (existing === undefined) {
280	    changes.push({ _tag: "PersonAdded", person });
281	  } else if (existing.removedAt !== null) {
282	    changes.push({ _tag: "PersonRestored", personId: existing.id });
283	  }
284	
285	  const index: FollowUp = { _tag: "IndexPerson", person: refOf(person) };
286	  const current = existing === undefined ? undefined : activeMembershipOf(state, team.id, existing.id);
287	
288	  if (current !== undefined && (current.role === role || current.role === "lead")) {
289	    return accept(changes, [index]);
290	  }
291	
292	  const membership: MembershipRecord = {
293	    id: member.membershipId,
294	    teamId: team.id,
295	    personId: person.id,
296	    role,
297	    startedAt: now,
298	    endedAt: null,
299	  };
300	
301	  if (current !== undefined) {
302	    changes.push(
303	      { _tag: "MembershipEnded", membershipId: current.id, at: now },
304	      { _tag: "MembershipStarted", membership },
305	    );
306	
307	    return accept(changes, [index]);
308	  }
309	
310	  const sendId = addedEmailSendId(membership.id);
311	  changes.push(
312	    { _tag: "MembershipStarted", membership },
313	    {
314	      _tag: "EmailRequested",
315	      sendId,
316	      recipient: person.email,
317	      email: {
318	        _tag: "AddedToTeam",
319	        locale: emailLocaleOf(state, person.id),
320	        teamName: team.name,
321	        leadName: adder.email,
322	        signInUrl: member.signInUrl,
323	      },
324	    },
325	  );
326	
327	  return accept(changes, [index]);
328	};
329	
330	export const decide = (
331	  state: DirectoryState,
332	  actorId: PersonId,
333	  command: DirectoryCommand,
334	  now: number,
335	): Decision => {
336	  const actor = actorOf(state, actorId);
337	  const adder = state.people.find((person) => person.id === actorId);
338	
339	  if (Option.isNone(actor) || adder === undefined) {
340	    return forbidden;
341	  }
342	
343	  const allowed = actor.value;
344	  const organization = { _tag: "Organization" } as const;
345	
346	  switch (command._tag) {
347	    case "CreateTeam": {
348	      if (!can(allowed, "organization.createTeam", organization)) {
349	        return forbidden;
350	      }
351	
352	      if (nameTaken(state, command.name)) {
353	        return reject({ _tag: "TeamNameTaken" });
354	      }
355	
356	      const team: TeamRecord = { id: command.teamId, name: command.name, timeZone: command.timeZone };
357	
358	      if (findTeam(state, team.id) !== undefined) {
359	        return reject({ _tag: "TeamNameTaken" });
360	      }
361	
362	      const withTeam: DirectoryState = { ...state, teams: [...state.teams, team] };
363	      const lead = putInTeam(withTeam, adder, team, "lead", command.lead, now);
364	
365	      if (lead._tag === "Rejected") {
366	        return lead;
367	      }
368	
369	      return accept([{ _tag: "TeamAdded", team }, ...lead.changes], lead.followUps);
370	    }
371	
372	    case "UpdateTeam": {
373	      if (!can(allowed, "team.update", { _tag: "Team", teamId: command.teamId })) {
374	        return forbidden;
375	      }
376	
377	      if (findTeam(state, command.teamId) === undefined) {
378	        return reject({ _tag: "TeamNotFound" });
379	      }
380	
381	      if (nameTaken(state, command.name, command.teamId)) {
382	        return reject({ _tag: "TeamNameTaken" });
383	      }
384	
385	      return accept([
386	        { _tag: "TeamUpdated", team: { id: command.teamId, name: command.name, timeZone: command.timeZone } },
387	      ]);
388	    }
389	
390	    case "AddMember": {
391	      const action = command.role === "lead" ? "team.assignLead" : "team.addMember";
392	
393	      if (!can(allowed, action, { _tag: "Team", teamId: command.teamId })) {
394	        return forbidden;
395	      }
396	
397	      const team = findTeam(state, command.teamId);
398	
399	      if (team === undefined) {
400	        return reject({ _tag: "TeamNotFound" });
401	      }
402	
403	      return putInTeam(state, adder, team, command.role, command.member, now);
404	    }
405	
406	    case "RemoveMember": {
407	      const resource = { _tag: "Team", teamId: command.teamId } as const;
408	
409	      if (!can(allowed, "team.removeMember", resource)) {
410	        return forbidden;
411	      }
412	
413	      if (findTeam(state, command.teamId) === undefined) {
414	        return reject({ _tag: "TeamNotFound" });
415	      }
416	
417	      const membership = activeMembershipOf(state, command.teamId, command.personId);
418	
419	      if (membership === undefined) {
420	        return reject({ _tag: "PersonNotFound" });
421	      }
422	
423	      if (membership.role === "lead") {
424	        if (!can(allowed, "team.removeLead", resource)) {
425	          return forbidden;
426	        }
427	
428	        if (leadsOf(state, command.teamId).length <= 1) {
429	          return reject({ _tag: "LastLead", teamId: command.teamId });
430	        }
431	      }
432	
433	      return accept([{ _tag: "MembershipEnded", membershipId: membership.id, at: now }]);
434	    }
435	
436	    case "RemoveLead": {
437	      if (!can(allowed, "team.removeLead", { _tag: "Team", teamId: command.teamId })) {
438	        return forbidden;
439	      }
440	
441	      if (findTeam(state, command.teamId) === undefined) {
442	        return reject({ _tag: "TeamNotFound" });
443	      }
444	
445	      const membership = activeMembershipOf(state, command.teamId, command.personId);
446	
447	      if (membership?.role !== "lead") {
448	        return reject({ _tag: "PersonNotFound" });
449	      }
450	
451	      if (leadsOf(state, command.teamId).length <= 1) {
452	        return reject({ _tag: "LastLead", teamId: command.teamId });
453	      }
454	
455	      return accept([
456	        { _tag: "MembershipEnded", membershipId: membership.id, at: now },
457	        {
458	          _tag: "MembershipStarted",
459	          membership: {
460	            id: command.membershipId,
461	            teamId: command.teamId,
462	            personId: command.personId,
463	            role: "member",
464	            startedAt: now,
465	            endedAt: null,
466	          },
467	        },
468	      ]);
469	    }
470	
471	    case "RemovePerson": {
472	      if (!can(allowed, "organization.removePerson", organization)) {
473	        return forbidden;
474	      }
475	
476	      if (command.personId === actorId) {
477	        return forbidden;
478	      }
479	
480	      const person = state.people.find((each) => each.id === command.personId);
481	
482	      if (person === undefined) {
483	        return reject({ _tag: "PersonNotFound" });
484	      }
485	
486	      const followUps: FollowUp[] = [{ _tag: "UnindexPerson", personId: person.id }];
487	
488	      if (person.removedAt !== null) {
489	        return accept([], followUps);
490	      }
491	
492	      const memberships = state.memberships.filter(
493	        (membership) => membership.personId === person.id && isActive(membership),
494	      );
495	
496	      for (const membership of memberships) {
497	        if (membership.role === "lead" && leadsOf(state, membership.teamId).length <= 1) {
498	          return reject({ _tag: "LastLead", teamId: membership.teamId });
499	        }
500	      }
501	
502	      if (
503	        person.organizationAdmin &&
504	        activePeople(state).filter((each) => each.organizationAdmin).length <= 1
505	      ) {
506	        return reject({ _tag: "LastAdmin" });
507	      }
508	
509	      const changes: DirectoryChange[] = memberships.map((membership) => ({
510	        _tag: "MembershipEnded",
511	        membershipId: membership.id,
512	        at: now,
513	      }));
514	
515	      if (person.organizationAdmin) {
516	        changes.push({ _tag: "AdminSet", personId: person.id, organizationAdmin: false });
517	      }
518	
519	      changes.push({ _tag: "PersonRemoved", personId: person.id, at: now });
520	
521	      return accept(changes, followUps);
522	    }
523	
524	    case "SetAdmin": {
525	      if (!can(allowed, "organization.setAdmin", organization)) {
526	        return forbidden;
527	      }
528	
529	      const person = activePeople(state).find((each) => each.id === command.personId);
530	
531	      if (person === undefined) {
532	        return reject({ _tag: "PersonNotFound" });
533	      }
534	
535	      if (
536	        person.organizationAdmin &&
537	        !command.organizationAdmin &&
538	        activePeople(state).filter((each) => each.organizationAdmin).length <= 1
539	      ) {
540	        return reject({ _tag: "LastAdmin" });
541	      }
542	
543	      if (person.organizationAdmin === command.organizationAdmin) {
544	        return accept([]);
545	      }
546	
547	      return accept([
548	        { _tag: "AdminSet", personId: person.id, organizationAdmin: command.organizationAdmin },
549	      ]);
550	    }
551	
552	    case "UpdateSettings": {
553	      if (!can(allowed, "organization.updateSettings", organization)) {
554	        return forbidden;
555	      }
556	
557	      return accept([
558	        {
559	          _tag: "SettingsUpdated",
560	          minimumGroupSize: command.minimumGroupSize ?? state.minimumGroupSize,
561	          aiProcessing: command.aiProcessing ?? state.aiProcessing,
562	          defaultLocale: command.defaultLocale ?? state.defaultLocale,
563	        },
564	      ]);
565	    }
566	
567	    case "UpdateOwnLanguage": {
568	      return accept([
569	        {
570	          _tag: "PersonLanguageSet",
571	          personId: actorId,
572	          locale: command.locale === undefined ? adder.locale : command.locale,
573	          detectedLocale: command.detectedLocale ?? adder.detectedLocale,
574	        },
575	      ]);
576	    }
577	  }
578	};
579	
580	const applyChange = (state: DirectoryState, change: DirectoryChange): DirectoryState => {
581	  const updatePerson = (personId: PersonId, update: (person: PersonRecord) => PersonRecord) => ({
582	    ...state,
583	    people: state.people.map((person) => (person.id === personId ? update(person) : person)),
584	  });
585	
586	  switch (change._tag) {
587	    case "PersonAdded": {
588	      return { ...state, people: [...state.people, change.person] };
589	    }
590	
591	    case "PersonRestored": {
592	      return updatePerson(change.personId, (person) => ({ ...person, removedAt: null }));
593	    }
594	
595	    case "PersonRemoved": {
596	      return updatePerson(change.personId, (person) => ({ ...person, removedAt: change.at }));
597	    }
598	
599	    case "AdminSet": {
600	      return updatePerson(change.personId, (person) => ({
601	        ...person,
602	        organizationAdmin: change.organizationAdmin,
603	      }));
604	    }
605	
606	    case "TeamAdded": {
607	      return { ...state, teams: [...state.teams, change.team] };
608	    }
609	
610	    case "TeamUpdated": {
611	      return {
612	        ...state,
613	        teams: state.teams.map((team) => (team.id === change.team.id ? change.team : team)),
614	      };
615	    }
616	
617	    case "MembershipStarted": {
618	      return { ...state, memberships: [...state.memberships, change.membership] };
619	    }
620	
621	    case "MembershipEnded": {
622	      return {
623	        ...state,
624	        memberships: state.memberships.map((membership) =>
625	          membership.id === change.membershipId ? { ...membership, endedAt: change.at } : membership,
626	        ),
627	      };
628	    }
629	
630	    case "SettingsUpdated": {
631	      return {
632	        ...state,
633	        minimumGroupSize: change.minimumGroupSize,
634	        aiProcessing: change.aiProcessing,
635	        defaultLocale: change.defaultLocale,
636	      };
637	    }
638	
639	    case "PersonLanguageSet": {
640	      return updatePerson(change.personId, (person) => ({
641	        ...person,
642	        locale: change.locale,
643	        detectedLocale: change.detectedLocale,
644	      }));
645	    }
646	
647	    case "EmailRequested": {
648	      return state;
649	    }
650	  }
651	};
652	
653	export const applyChanges = (state: DirectoryState, changes: readonly DirectoryChange[]): DirectoryState => {
654	  let current = state;
655	
656	  for (const change of changes) {
657	    current = applyChange(current, change);
658	  }
659	
660	  return current;
661	};
