663	export const teamSummaryOf = (team: TeamRecord, actor: Actor, memberCount?: number): TeamSummary => ({
664	  id: team.id,
665	  name: team.name,
666	  timeZone: team.timeZone,
667	  yourRole: actor.roles.get(team.id) ?? null,
668	
669	  ...(memberCount === undefined ? {} : { memberCount }),
670	});
671	
672	const activeMembersOf = (state: DirectoryState, teamId: TeamId): number =>
673	  state.memberships.filter((membership) => membership.teamId === teamId && membership.endedAt === null)
674	    .length;
675	
676	const byName = (a: { readonly name: string }, b: { readonly name: string }) =>
677	  a.name.localeCompare(b.name, "en");
678	
679	export const teamsView = (state: DirectoryState, actorId: PersonId): Viewed<readonly TeamSummary[]> => {
680	  const actor = actorOf(state, actorId);
681	
682	  if (Option.isNone(actor)) {
683	    return forbidden;
684	  }
685	
686	  const listAll = can(actor.value, "organization.listTeams", { _tag: "Organization" });
687	
688	  const teams = state.teams.filter(
689	    (team) => listAll || can(actor.value, "team.view", { _tag: "Team", teamId: team.id }),
690	  );
691	
692	  return {
693	    _tag: "Viewed",
694	    value: [...teams]
695	      .sort(byName)
696	      .map((team) => teamSummaryOf(team, actor.value, activeMembersOf(state, team.id))),
697	  };
698	};
699	
700	const ROLE_ORDER: Readonly<Record<MembershipRole, number>> = { lead: 0, member: 1, viewer: 2 };
701	
702	export const teamView = (state: DirectoryState, actorId: PersonId, teamId: TeamId): Viewed<TeamDetail> => {
703	  const actor = actorOf(state, actorId);
704	
705	  if (Option.isNone(actor)) {
706	    return forbidden;
707	  }
708	
709	  const resource = { _tag: "Team", teamId } as const;
710	
711	  if (!can(actor.value, "team.viewRoster", resource)) {
712	    return forbidden;
713	  }
714	
715	  const team = findTeam(state, teamId);
716	
717	  if (team === undefined) {
718	    return reject({ _tag: "TeamNotFound" });
719	  }
720	
721	  const emails = new Map(state.people.map((person) => [person.id, person.email]));
722	
723	  const roster = activeMemberships(state, teamId)
724	    .flatMap((membership) => {
725	      const email = emails.get(membership.personId);
726	
727	      return email === undefined
728	        ? []
729	        : [{ personId: membership.personId, email, role: membership.role, since: membership.startedAt }];
730	    })
731	    .sort((a, b) => ROLE_ORDER[a.role] - ROLE_ORDER[b.role] || a.email.localeCompare(b.email, "en"));
732	
733	  return {
734	    _tag: "Viewed",
735	    value: {
736	      team: teamSummaryOf(team, actor.value, activeMembersOf(state, team.id)),
737	      roster,
738	      may: {
739	        update: can(actor.value, "team.update", resource),
740	        manageLeads: can(actor.value, "team.assignLead", resource),
741	        manageMembers: can(actor.value, "team.addMember", resource),
742	        managePulses: can(actor.value, "team.editPulse", resource),
743	        viewResults: can(actor.value, "team.viewResults", resource),
744	      },
745	    },
746	  };
747	};
748	
749	export const settingsView = (state: DirectoryState, actorId: PersonId): Viewed<OrganizationSettings> => {
750	  const actor = actorOf(state, actorId);
751	
752	  if (Option.isNone(actor)) {
753	    return forbidden;
754	  }
755	
756	  if (!can(actor.value, "organization.viewSettings", { _tag: "Organization" })) {
757	    return forbidden;
758	  }
759	
760	  return {
761	    _tag: "Viewed",
762	    value: {
763	      name: state.organizationName,
764	      minimumGroupSize: state.minimumGroupSize,
765	      aiProcessing: state.aiProcessing,
766	      defaultLocale: state.defaultLocale,
767	      people: activePeople(state)
768	        .map((person) => ({
769	          personId: person.id,
770	          email: person.email,
771	          organizationAdmin: person.organizationAdmin,
772	          linked: person.authUserId !== null,
773	        }))
774	        .sort((a, b) => a.email.localeCompare(b.email, "en")),
775	    },
776	  };
