778	
779	export const isEmailAdmin = (state: DirectoryState, actorId: PersonId): boolean => {
780	  const actor = actorOf(state, actorId);
781	
782	  return Option.isSome(actor) && can(actor.value, "organization.updateSettings", { _tag: "Organization" });
783	};
784	
785	export const emailStatusView = (
786	  state: DirectoryState,
787	  actorId: PersonId,
788	  status: FailedEmailStatus | null,
789	): Viewed<FailedEmailStatus> => {
790	  if (!isEmailAdmin(state, actorId)) {
791	    return forbidden;
792	  }
793	
794	  if (status === null) {
795	    return reject({ _tag: "FailedEmailNotFound" });
796	  }
797	
798	  return { _tag: "Viewed", value: status };
799	};
