import { OrganizationId, SendId } from "@surveybeat/domain";
import type { SendStoreShape } from "@surveybeat/domain";
import * as Effect from "effect/Effect";
import * as Schema from "effect/Schema";
import { EmailSendRequested } from "../Email.ts";

const QUEUE_BATCH_LIMIT = 100;

const OutboxRow = Schema.Struct({ id: Schema.Int, send_id: SendId });

const decodeOutboxRows = Schema.decodeUnknownEffect(Schema.Array(OutboxRow));

const decodeOrganizationRows = Schema.decodeUnknownEffect(
  Schema.Array(Schema.Struct({ id: OrganizationId })),
);

const encodeRequest = Schema.encodeEffect(EmailSendRequested);

export const makeEmailOutbox = (
  sql: SqliteClient.SqliteClient,
  queue: Cloudflare.Queues.WriteQueueClient,
) => {
  const record = (id: SendId) =>
    sql`INSERT INTO email_outbox (send_id) VALUES (${id})`.pipe(Effect.asVoid, Effect.orDie);

  const recording = (store: SendStoreShape, afterRecord: Effect.Effect<void>): SendStoreShape => ({
    ...store,
    create: (id, recipient, email) =>
      store
        .create(id, recipient, email)
        .pipe(
          Effect.tap((state) =>
            state._tag === "Pending" ? Effect.andThen(record(id), afterRecord) : Effect.void,
          ),
        ),
    requeue: (id) =>
      store
        .requeue(id)
        .pipe(
          Effect.tap((result) =>
            result._tag === "Requeued" ? Effect.andThen(record(id), afterRecord) : Effect.void,
          ),
        ),
  });

  const isWaiting = sql<{ waiting: number }>`SELECT EXISTS (SELECT 1 FROM email_outbox) AS waiting`.pipe(
    Effect.map((rows) => (rows[0]?.waiting ?? 0) === 1),
    Effect.orDie,
  );

  const dispatchBatch = Effect.gen(function* () {
    const rows = yield* sql`SELECT id, send_id FROM email_outbox ORDER BY id LIMIT ${QUEUE_BATCH_LIMIT}`.pipe(
      Effect.flatMap(decodeOutboxRows),
    );

    const last = rows.at(-1);

    if (last === undefined) {
      return false;
    }

    const [organization] = yield* sql`SELECT id FROM organization LIMIT 1`.pipe(
      Effect.flatMap(decodeOrganizationRows),
    );

    if (organization === undefined) {
      return yield* Effect.die("an Organization with sends has no organization row");
    }

    const messages = yield* Effect.forEach(rows, (row) =>
      encodeRequest({ organizationId: organization.id, sendId: row.send_id }).pipe(
        Effect.map((body) => ({ body })),
      ),
    );

    yield* queue.sendBatch(messages);
    yield* sql`DELETE FROM email_outbox WHERE id <= ${last.id}`;

    return rows.length === QUEUE_BATCH_LIMIT;
  });

  const dispatch = Effect.gen(function* () {
    while (yield* dispatchBatch) {}
  }).pipe(Effect.orDie);

  return { recording, isWaiting, dispatch };
};
import { Clock, Duration, Effect, Option } from "effect";
import type { SendId } from "./Email.ts";
import { EmailSender } from "./EmailSender.ts";
import { EmailTemplates } from "./EmailTemplates.ts";
import { retryDelaySeconds } from "./SendState.ts";
import type { SendOutcome, SendState } from "./SendState.ts";
import { SendStore } from "./SendStore.ts";
import type { ClaimResult } from "./SendStore.ts";

export const sendTimeout = Duration.seconds(30);

export type DeliveryResult =
  | { readonly _tag: "Done"; readonly state: SendState | null }
  | { readonly _tag: "RetryAfter"; readonly seconds: number };

export const deliver = Effect.fn("deliver")(function* (id: SendId) {
  const store = yield* SendStore;
  const claimed = yield* store.claim(id, yield* Clock.currentTimeMillis);

  switch (claimed._tag) {
    case "Missing": {
      return done(null);
    }

    case "Finished": {
      return done(claimed.state);
    }

    case "Wait": {
      const now = yield* Clock.currentTimeMillis;

      return retryAfter(Math.max(1, Math.ceil((claimed.until - now) / 1000)));
    }

    case "Send": {
      const outcome = yield* attempt(claimed);
      const state = yield* store.settle(id, claimed.attempt, outcome, yield* Clock.currentTimeMillis);

      if (Option.isSome(state) && state.value._tag === "Pending") {
        return retryAfter(retryDelaySeconds(claimed.attempt));
      }

      return done(Option.getOrNull(state));
    }
  }
});

const attempt = (claimed: Extract<ClaimResult, { _tag: "Send" }>) =>
  Effect.gen(function* () {
    const templates = yield* EmailTemplates;
    const sender = yield* EmailSender;

    const rendered = yield* templates.render(claimed.email).pipe(Effect.exit);

    if (rendered._tag === "Failure") {
      return rejected("E_RENDER_FAILED", true);
    }

    return yield* sender.send({ to: claimed.recipient, ...rendered.value }).pipe(
      Effect.timeout(sendTimeout),
      Effect.map((accepted): SendOutcome => ({ _tag: "Accepted", messageId: accepted.messageId })),
      Effect.catchTags({
        EmailRejected: (error) => Effect.succeed(rejected(error.code, error.permanent)),
        EmailOutcomeUnknown: (error) => Effect.succeed(unknown(error.code)),
        TimeoutError: () => Effect.succeed(unknown("E_TIMEOUT")),
      }),
      Effect.catchDefect(() => Effect.succeed(unknown("E_DEFECT"))),
    );
  });

const done = (state: SendState | null): DeliveryResult => ({ _tag: "Done", state });

const retryAfter = (seconds: number): DeliveryResult => ({ _tag: "RetryAfter", seconds });

const rejected = (code: string, permanent: boolean): SendOutcome => ({ _tag: "Rejected", code, permanent });

const unknown = (code: string): SendOutcome => ({ _tag: "Unknown", code });

