        Story.message(Message.SelfEraseOpened()),
        Story.message(Message.SelfEraseConfirmationChanged({ value: "alice@acme.com" })),
        Story.message(Message.SelfEraseSubmitted()),
        Story.Command.expectHas(EraseOwnAccountData),
      );
    });
  });

